    (SELECT COUNT(*) * 100.0 / (SELECT COUNT(*) FROM member WHERE position = 'Member') FROM member JOIN zip_code ON member.zip = zip_code.zip_code WHERE member.position = 'Member' AND zip_code.state = 'New Jersey') - 
    (SELECT COUNT(*) * 100.0 / (SELECT COUNT(*) FROM member WHERE position = 'Member') FROM member JOIN zip_code ON member.zip = zip_code.zip_code WHERE member.position = 'Member' AND zip_code.state = 'Vermont') AS percentage_difference;

